// Selecting the next process to run.
// higher_priority() must encode whichever convention this
// system actually uses (lower number wins, or higher number
// wins) and must be applied consistently everywhere.

Process pick_next(ReadyQueue queue) {
    Process best = queue[0];
    for (Process p : queue) {
        if (higher_priority(p, best)) {
            best = p;
        }
    }
    return best;
}

